public class SqlParser {

    public static void main(String[] args) {
        String dbType = JdbcConstants.MYSQL.name();
        String sql = "SELECT `业务质量`,`区域`,`门店`,`当日线下线索`,`当日线下线索GAP`,`当日线下线索完成率`,`当日试驾量`,`当日试驾GAP`,`当日试驾完成率`,`当日净锁单`,`当日净锁单GAP`,`当日净锁单完成率`,`当周线下线索`,`当周线下线索完成率`,`当周试驾量`,`当周试驾完成率`,`当周净锁单`,`当周净锁单完成率`,`当月当阶段净锁单`,`当月当阶段净锁单完成率`,`当月净锁单`,`当月净锁单完成率`,`客流转化率`,`线上线索到试驾转化率目标`,`线上线索到试驾转化率W1`,`线上线索到试驾转化率W2`,`线上线索到试驾转化率W3`,`线上线索到试驾转化率W4`,`线上线索到试驾转化率W5`,`试驾到锁单转化率目标`,`转化率W1`,`转化率W2`,`转化率W3`,`转化率W4`,`转化率W5` FROM (\n" +
                "SELECT '2021-10-12' AS '日期',area AS '区域',store_name AS '门店',MAX(CASE WHEN IF (leads_aim_day=0,0,leads_amount_day/leads_aim_day)>=1 AND IF (test_drive_aim_day=0,0,testdrive_amount_day/test_drive_aim_day)>=1 AND IF (locked_aim_day=0,0,locked_amount_day/locked_aim_day)>=1 THEN 3 WHEN IF (leads_aim_day=0,0,leads_amount_day/leads_aim_day)>=1 AND IF (test_drive_aim_day=0,0,testdrive_amount_day/test_drive_aim_day)>=1 THEN 2 WHEN IF (leads_aim_day=0,0,leads_amount_day/leads_aim_day)>=1 AND IF (locked_aim_day=0,0,locked_amount_day/locked_aim_day)>=1 THEN 2 WHEN IF (test_drive_aim_day=0,0,testdrive_amount_day/test_drive_aim_day)>=1 AND IF (locked_aim_day=0,0,locked_amount_day/locked_aim_day)>=1 THEN 2 WHEN IF (leads_aim_day=0,0,leads_amount_day/leads_aim_day)>=1 THEN 1 WHEN IF (test_drive_aim_day=0,0,testdrive_amount_day/test_drive_aim_day)>=1 THEN 1 WHEN IF (locked_aim_day=0,0,locked_amount_day/locked_aim_day)>=1 THEN 1 ELSE 0 END) AS '业务质量',MAX(leads_aim_day) AS '当日线下线索目标',MAX(leads_amount_day) AS '当日线下线索',MAX(leads_amount_day)-MAX(leads_aim_day) AS '当日线下线索GAP',IF (MAX(leads_aim_day)=0,0,MAX(leads_amount_day)/MAX(leads_aim_day)) AS '当日线下线索完成率',MAX(test_drive_aim_day) AS '当日试驾目标',MAX(testdrive_amount_day) AS '当日试驾量',MAX(testdrive_amount_day)-MAX(test_drive_aim_day) AS '当日试驾GAP',IF (MAX(test_drive_aim_day)=0,0,MAX(testdrive_amount_day)/MAX(test_drive_aim_day)) AS '当日试驾完成率',MAX(locked_aim_day) AS '当日净锁单目标',MAX(locked_amount_day) AS '当日净锁单',MAX(locked_amount_day)-MAX(locked_aim_day) AS '当日净锁单GAP',IF (MAX(locked_aim_day)=0,0,MAX(locked_amount_day)/MAX(locked_aim_day)) AS '当日净锁单完成率',MAX(leads_aim_week) AS '当周线下线索目标',MAX(leads_amount_week) AS '当周线下线索',MAX(leads_amount_week)-MAX(leads_aim_week) AS '当周线下线索GAP',IF (MAX(leads_aim_week)=0,0,MAX(leads_amount_week)/MAX(leads_aim_week)) AS '当周线下线索完成率',MAX(test_drive_aim_week) AS '当周试驾目标',MAX(testdrive_amount_week) AS '当周试驾量',MAX(testdrive_amount_week)-MAX(test_drive_aim_week) AS '当周试驾GAP',IF (MAX(test_drive_aim_week)=0,0,MAX(testdrive_amount_week)/MAX(test_drive_aim_week)) AS '当周试驾完成率',MAX(locked_aim_week) AS '当周净锁单目标',MAX(locked_amount_week) AS '当周净锁单',MAX(locked_amount_week)-MAX(locked_aim_week) AS '当周净锁单GAP',IF (MAX(locked_aim_week)=0,0,MAX(locked_amount_week)/MAX(locked_aim_week)) AS '当周净锁单完成率',MAX(locked_aim_month) AS '当月净锁单目标',MAX(locked_aim_month_16) AS '当月当阶段净锁单目标',MAX(locked_amount_16days) AS '当月当阶段净锁单',MAX(locked_amount_16days)/MAX(locked_aim_month_16) AS '当月当阶段净锁单完成率',MAX(locked_amount_month) AS '当月净锁单',IF (MAX(locked_aim_month)=0,0,MAX(locked_amount_month)/MAX(locked_aim_month)) AS '当月净锁单完成率',MAX(volume_rate) AS '客流转化率',MAX(lead_online_drive_aim_week) AS '线上线索到试驾转化率目标',MAX(leads_drive_1) AS '线上线索到试驾转化率W1',MAX(leads_drive_2) AS '线上线索到试驾转化率W2',MAX(leads_drive_3) AS '线上线索到试驾转化率W3',MAX(leads_drive_4) AS '线上线索到试驾转化率W4',MAX(leads_drive_5) AS '线上线索到试驾转化率W5',MAX(drive_locked_aim_week) AS '试驾到锁单转化率目标',MAX(drive_locked_1) AS '转化率W1',MAX(drive_locked_2) AS '转化率W2',MAX(drive_locked_3) AS '转化率W3',MAX(drive_locked_4) AS '转化率W4',MAX(drive_locked_5) AS '转化率W5' FROM (\n" +
                "SELECT t3.area,t3.store_name,MAX(t3.dept_seq) AS dept_seq,MAX(CASE WHEN t4.flag=1 AND t4.start_day='2021-10-12' AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t4.leads_aim ELSE 0 END) AS leads_aim_day,SUM(CASE WHEN t4.flag=1 AND t4.start_day='2021-10-12' AND t3.flag='leads' AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t3.cs ELSE 0 END) AS leads_amount_day,MAX(CASE WHEN t4.flag=1 AND t4.start_day='2021-10-12' AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t4.test_drive_aim ELSE 0 END) AS test_drive_aim_day,SUM(CASE WHEN t4.flag=1 AND t4.start_day='2021-10-12' AND t3.flag='testdrive' AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t3.cs ELSE 0 END) AS testdrive_amount_day,MAX(CASE WHEN t4.flag=1 AND t4.start_day='2021-10-12' AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t4.locked_aim ELSE 0 END) AS locked_aim_day,SUM(CASE WHEN t4.flag=1 AND t4.start_day='2021-10-12' AND t3.flag='locked' AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t3.cs ELSE 0 END) AS locked_amount_day,MAX(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<='2021-10-12' AND t4.end_day>='2021-10-12' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t4.leads_aim ELSE 0 END) AS leads_aim_week,SUM(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<='2021-10-12' AND t4.end_day>='2021-10-12' AND t3.flag='leads' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t3.cs ELSE 0 END) AS leads_amount_week,MAX(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<='2021-10-12' AND t4.end_day>='2021-10-12' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t4.test_drive_aim ELSE 0 END) AS test_drive_aim_week,SUM(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<='2021-10-12' AND t4.end_day>='2021-10-12' AND t3.flag='testdrive' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t3.cs ELSE 0 END) AS testdrive_amount_week,MAX(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<='2021-10-12' AND t4.end_day>='2021-10-12' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t4.locked_aim ELSE 0 END) AS locked_aim_week,SUM(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<='2021-10-12' AND t4.end_day>='2021-10-12' AND t3.flag='locked' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t3.cs ELSE 0 END) AS locked_amount_week,MAX(CASE WHEN t4.flag=31 AND t4.start_day<='2021-10-12' AND t4.end_day>='2021-10-12' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t4.locked_aim ELSE 0 END) AS locked_aim_month,MAX(CASE WHEN t4.flag=16 AND t4.start_day<='2021-10-12' AND t4.end_day>='2021-10-12' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t4.locked_aim ELSE 0 END) AS locked_aim_month_16,SUM(CASE WHEN t4.flag=16 AND t4.start_day<='2021-10-12' AND t4.end_day>='2021-10-12' AND t3.flag='locked' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t3.cs ELSE 0 END) AS locked_amount_16days,SUM(CASE WHEN t4.flag=31 AND t4.start_day<='2021-10-12' AND t4.end_day>='2021-10-12' AND t3.flag='locked' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t3.cs ELSE 0 END) AS locked_amount_month,0 AS volume_rate,0 AS lead_online_drive_aim_week,0 AS leads_drive_1,0 AS leads_drive_2,0 AS leads_drive_3,0 AS leads_drive_4,0 AS leads_drive_5,0 AS drive_locked_aim_week,0 AS drive_locked_1,0 AS drive_locked_2,0 AS drive_locked_3,0 AS drive_locked_4,0 AS drive_locked_5 FROM (\n" +
                "SELECT t1.id,t1.area,t1.store_name,t1.dept_seq,IFNULL(t2.day_key,'2021-10-12') AS day_key,flag,customer_account_id,cs FROM (\n" +
                "SELECT owner_store_dept_id AS id,owner_store_dept_name AS store_name,dept_id,area,dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT area_dept_id AS id,'总计' AS store_name,dept_id,area,area_seq AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,dept_id,'全国' AS area,0 AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,999 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,0 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 0 AS id,'总计' store_name,0 AS dept_id,'云订单' AS area,999 AS dept_seq) t1 LEFT OUTER JOIN (\n" +
                "SELECT day_key,real_dept_id,flag,customer_account_id,count(1) cs FROM (\n" +
                "SELECT leads.day_key,'leads' AS flag,leads.customer_account_id,IFNULL(owner_dept_id,999) AS real_dept_id FROM (\n" +
                "SELECT DATE_FORMAT(leads_create_time,'%Y-%m-%d') AS day_key,customer_account_id FROM da_dmp_tidb.nr_sales_leads_detail_table WHERE leads_create_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND leads_create_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') AND is_net_leads=1 AND business_type_name='线下') leads LEFT OUTER JOIN (\n" +
                "SELECT customer_account_id,owner_dept_id,ROW_NUMBER() OVER (PARTITION BY customer_account_id ORDER BY create_time) AS rk FROM saos_tur.rb_ticket WHERE create_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND create_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') AND `is_delete`=0 AND LENGTH(TRIM(customer_account_id)) !=0) ticket ON leads.customer_account_id=ticket.customer_account_id AND ticket.rk=1 UNION ALL \n" +
                "SELECT DATE_FORMAT(begin_time,'%Y-%m-%d') AS day_key,'testdrive' AS flag,customer_account_id,dept_id AS real_dept_id FROM saos_tur.rb_attempt_drive_record WHERE begin_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND begin_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') AND `is_delete`=0 UNION ALL \n" +
                "SELECT locked.day_key,'locked' AS flag,locked.customer_account_id,IFNULL(orders.employee_dept_id,0) AS real_dept_id FROM (\n" +
                "SELECT DATE_FORMAT(locked_time,'%Y-%m-%d') AS day_key,customer_account_id,sales_order_id FROM da_dmp_tidb.nr_sales_lock_detail WHERE is_clear=1 AND locked_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND locked_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) locked LEFT OUTER JOIN (\n" +
                "SELECT customer_account_id,order_code,employee_dept_id FROM saos_tur.tur_employee_order_bind WHERE lock_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND employee_type=1 AND employee_account_id<> '000000') orders ON locked.sales_order_id=orders.order_code) act GROUP BY day_key,real_dept_id,flag,customer_account_id) t2 ON t1.dept_id=t2.real_dept_id) t3 LEFT OUTER JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,id,store_code,leads_aim,test_drive_aim,locked_aim FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE DATE_FORMAT('2021-10-12','%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-%d') AND DATE_FORMAT('2021-10-12','%Y-%m-%d')<=DATE_FORMAT(end_day,'%Y-%m-%d') UNION ALL \n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,0 AS id,0 AS store_code,0 AS leads_aim,0 AS test_drive_aim,0 AS locked_aim FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE DATE_FORMAT('2021-10-12','%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-%d') AND DATE_FORMAT('2021-10-12','%Y-%m-%d')<=DATE_FORMAT(end_day,'%Y-%m-%d')) t4 ON t3.id=t4.id GROUP BY t3.area,t3.store_name UNION ALL \n" +
                "SELECT t3.area,t3.store_name,MAX(t3.dept_seq) AS dept_seq,0 AS leads_aim_day,0 AS leads_amount_day,0 AS test_drive_aim_day,0 AS testdrive_amount_day,0 AS locked_aim_day,0 AS locked_amount_day,0 AS leads_aim_week,0 AS leads_amount_week,0 AS test_drive_aim_week,0 AS testdrive_amount_week,0 AS locked_aim_week,0 AS locked_amount_week,0 AS locked_aim_month,0 AS locked_aim_month_16,0 AS locked_amount_16days,0 AS locked_amount_month,IF (MAX(volume)=0,0,IFNULL((MAX(leads_cs)-MAX(act_leads_cs))/MAX(volume),0)) AS volume_rate,0 AS lead_online_drive_aim_week,0 AS leads_drive_1,0 AS leads_drive_2,0 AS leads_drive_3,0 AS leads_drive_4,0 AS leads_drive_5,0 AS drive_locked_aim_week,0 AS drive_locked_1,0 AS drive_locked_2,0 AS drive_locked_3,0 AS drive_locked_4,0 AS drive_locked_5 FROM (\n" +
                "SELECT t1.area,t1.store_name,t1.dept_seq,SUM(IFNULL(t2.leads_cs,0)) leads_cs,SUM(IFNULL(t2.act_leads_cs,0)) act_leads_cs,SUM(IFNULL(t2.volume,0)) volume FROM (\n" +
                "SELECT owner_store_dept_id AS id,owner_store_dept_name AS store_name,dept_id,area,dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT area_dept_id AS id,'总计' AS store_name,dept_id,area,area_seq AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,dept_id,'全国' AS area,0 AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,999 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,0 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 0 AS id,'总计' store_name,0 AS dept_id,'云订单' AS area,999 AS dept_seq) t1 LEFT OUTER JOIN (\n" +
                "SELECT owner_dept_id AS dept_id,MAX(leads_cs) leads_cs,MAX(act_leads_cs) act_leads_cs,MAX(volume) volume FROM (\n" +
                "SELECT owner_dept_id,0 AS leads_cs,COUNT(1) act_leads_cs,0 AS volume FROM (\n" +
                "SELECT t1.leads_account_id customer_account_id,biz_code,t4.owner_dept_id,row_number() over (PARTITION BY t1.leads_account_id,t2.act_code ORDER BY t1.create_time) num FROM (\n" +
                "SELECT leads_account_id,create_time,biz_code,lead_uniq_code FROM (\n" +
                "SELECT 0 AS id,leads_account_id,create_time,biz_code,lead_uniq_code FROM saos_ccp.ccp_leads WHERE biz_code IS NOT NULL AND channel_code IN (102010) AND create_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND create_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) leads JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,0 AS id FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE flag MOD 7=0 AND id=999 AND DATE_FORMAT('2021-10-12','%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-%d') AND DATE_FORMAT('2021-10-12','%Y-%m-%d')<=DATE_FORMAT(end_day,'%Y-%m-%d')) dates ON leads.id=dates.id AND dates.start_day<=DATE_FORMAT(leads.create_time,'%Y-%m-%d') AND dates.end_day>=DATE_FORMAT(leads.create_time,'%Y-%m-%d')) t1 JOIN (\n" +
                "SELECT act_code,act_name FROM saos_mam.ma_act WHERE act_name NOT LIKE '%测试%') t2 ON t1.biz_code=t2.act_code JOIN saos_tur.rb_leads_oppty_releation t3 ON t1.lead_uniq_code=t3.leads_code JOIN (\n" +
                "SELECT owner_dept_id,oppty_code,row_number() over (PARTITION BY oppty_code ORDER BY create_time) num FROM da_dmp_tidb.nr_sales_ticket_detail) t4 ON t3.oppty_code=t4.oppty_code AND t4.num=1) t WHERE num=1 GROUP BY owner_dept_id UNION ALL \n" +
                "SELECT owner_dept_id,COUNT(1) AS leads_cs,0 AS act_leads_cs,0 AS volume FROM (\n" +
                "SELECT day_key,customer_account_id,channel_code FROM (\n" +
                "SELECT DATE_FORMAT(leads_create_time,'%Y-%m-%d') AS day_key,customer_account_id,channel_code,0 AS id FROM da_dmp_tidb.nr_sales_leads_detail_table WHERE leads_create_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND leads_create_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') AND is_net_leads=1 AND business_type_name='线下') leads1 JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,0 AS id FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE flag MOD 7=0 AND id=999 AND DATE_FORMAT('2021-10-12','%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-%d') AND DATE_FORMAT('2021-10-12','%Y-%m-%d')<=DATE_FORMAT(end_day,'%Y-%m-%d')) dates ON leads1.id=dates.id AND dates.start_day<=leads1.day_key AND dates.end_day>=leads1.day_key) leads JOIN (\n" +
                "SELECT customer_account_id,owner_dept_id,ROW_NUMBER() OVER (PARTITION BY customer_account_id ORDER BY create_time) AS rk FROM saos_tur.rb_ticket WHERE create_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND create_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') AND `is_delete`=0 AND LENGTH(TRIM(customer_account_id)) !=0) ticket ON leads.customer_account_id=ticket.customer_account_id AND ticket.rk=1 GROUP BY owner_dept_id UNION ALL \n" +
                "SELECT t4.id AS owner_dept_id,0 AS leads_cs,0 AS act_leads_cs,sum(volume) volume FROM (\n" +
                "SELECT camera_uuid,volume FROM (\n" +
                "SELECT DATE_FORMAT(date,'%Y-%m-%d') day_key,camera_uuid,sum(passengers_in) volume,0 AS id FROM coa.hikvision_footfall WHERE date>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND date< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') GROUP BY DATE_FORMAT(date,'%Y-%m-%d'),camera_uuid) hik JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,0 AS id FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE flag MOD 7=0 AND id=999 AND DATE_FORMAT('2021-10-12','%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-%d') AND DATE_FORMAT('2021-10-12','%Y-%m-%d')<=DATE_FORMAT(end_day,'%Y-%m-%d')) dates ON hik.id=dates.id AND dates.start_day<=hik.day_key AND dates.end_day>=hik.day_key) t1 JOIN (\n" +
                "SELECT DISTINCT camera_uuid,store_id FROM coa.hikvision_camera_device) t2 ON t1.camera_uuid=t2.camera_uuid JOIN (\n" +
                "SELECT DISTINCT CASE WHEN store_code='RTNA02' THEN 'RTNA01' ELSE store_code END AS store_code,hk_store_code FROM saos_tur.tur_store_hk_relation) t3 ON t2.store_id=t3.hk_store_code JOIN (\n" +
                "SELECT id,store_code FROM saos_tur.upm_dept WHERE `is_delete`=0 AND dept_type=20) t4 ON t3.store_code=t4.store_code GROUP BY t4.id) actleads GROUP BY owner_dept_id) t2 ON t1.dept_id=t2.dept_id GROUP BY t1.area,t1.store_name,t1.dept_seq) t3 GROUP BY t3.area,t3.store_name UNION ALL \n" +
                "SELECT t3.area,t3.store_name,MAX(t3.dept_seq) AS dept_seq,0 AS leads_aim_day,0 AS leads_amount_day,0 AS test_drive_aim_day,0 AS testdrive_amount_day,0 AS locked_aim_day,0 AS locked_amount_day,0 AS leads_aim_week,0 AS leads_amount_week,0 AS test_drive_aim_week,0 AS testdrive_amount_week,0 AS locked_aim_week,0 AS locked_amount_week,0 AS locked_aim_month,0 AS locked_aim_month_16,0 AS locked_amount_16days,0 AS locked_amount_month,0 AS volume_rate,0 AS lead_online_drive_aim_week,0 AS leads_drive_1,0 AS leads_drive_2,0 AS leads_drive_3,0 AS leads_drive_4,0 AS leads_drive_5,MAX(CASE WHEN t4.flag MOD 7=0 THEN t4.drive_locked_aim ELSE 0 END) AS drive_locked_aim_week,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=1 AND bhv_flag='order' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.locked_time>=t4.start_day AND t3.locked_time<=t4.end_day AND t3.attempt_time<=t3.locked_time THEN t3.vehicle_order_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=1 AND bhv_flag='attempt' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day THEN t3.customer_account_id END),0) AS drive_locked_1,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=2 AND bhv_flag='order' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.locked_time>=t4.start_day AND t3.locked_time<=t4.end_day AND t3.attempt_time<=t3.locked_time THEN t3.vehicle_order_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=2 AND bhv_flag='attempt' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day THEN t3.customer_account_id END),0) AS drive_locked_2,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=3 AND bhv_flag='order' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.locked_time>=t4.start_day AND t3.locked_time<=t4.end_day AND t3.attempt_time<=t3.locked_time THEN t3.vehicle_order_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=3 AND bhv_flag='attempt' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day THEN t3.customer_account_id END),0) AS drive_locked_3,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=4 AND bhv_flag='order' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.locked_time>=t4.start_day AND t3.locked_time<=t4.end_day AND t3.attempt_time<=t3.locked_time THEN t3.vehicle_order_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=4 AND bhv_flag='attempt' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day THEN t3.customer_account_id END),0) AS drive_locked_4,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=5 AND bhv_flag='order' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.locked_time>=t4.start_day AND t3.locked_time<=t4.end_day AND t3.attempt_time<=t3.locked_time THEN t3.vehicle_order_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=5 AND bhv_flag='attempt' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day THEN t3.customer_account_id END),0) AS drive_locked_5 FROM (\n" +
                "SELECT t1.id,t1.area,t1.store_name,t1.dept_seq,t2.bhv_flag,t2.customer_account_id,t2.attempt_time,t2.locked_time,t2.vehicle_order_id FROM (\n" +
                "SELECT owner_store_dept_id AS id,owner_store_dept_name AS store_name,dept_id,area,dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT area_dept_id AS id,'总计' AS store_name,dept_id,area,area_seq AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,dept_id,'全国' AS area,0 AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,999 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,0 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 0 AS id,'总计' store_name,0 AS dept_id,'云订单' AS area,999 AS dept_seq) t1 LEFT OUTER JOIN (\n" +
                "SELECT 'attempt' AS bhv_flag,dept_id AS real_dept_id,customer_account_id,DATE_FORMAT(begin_time,'%Y-%m-%d') AS attempt_time,'' AS locked_time,'' AS vehicle_order_id FROM saos_tur.rb_attempt_drive_record WHERE begin_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND begin_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') UNION ALL \n" +
                "SELECT 'order' AS bhv_flag,locked.dept_id AS real_dept_id,locked.customer_account_id,attempt.attempt_time,locked.locked_time,locked.vehicle_order_id FROM (\n" +
                "SELECT vehicle_order_id,locked_time,locked.customer_account_id,IFNULL(orders.dept_id,0) AS dept_id FROM (\n" +
                "SELECT vehicle_order_id,sales_order_id,DATE_FORMAT(locked_time,'%Y-%m-%d') AS locked_time,customer_account_id FROM da_dmp_tidb.nr_sales_lock_detail WHERE is_clear=1 AND sales_type<> 10 AND locked_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND locked_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) locked LEFT OUTER JOIN (\n" +
                "SELECT customer_account_id,employee_account_id,order_code,employee_dept_id AS dept_id FROM saos_tur.tur_employee_order_bind WHERE employee_type=1 AND lock_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND employee_account_id<> '000000') orders ON locked.sales_order_id=orders.order_code) locked LEFT OUTER JOIN (\n" +
                "SELECT attempt_code,customer_account_id,DATE_FORMAT(begin_time,'%Y-%m-%d') AS attempt_time,dept_id FROM saos_tur.rb_attempt_drive_record WHERE begin_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND begin_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) attempt ON attempt.customer_account_id=locked.customer_account_id) t2 ON t1.dept_id=t2.real_dept_id) t3 LEFT OUTER JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,id,store_code,drive_locked_aim FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE DATE_FORMAT('2021-10-12','%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-01') AND DATE_FORMAT('2021-10-12','%Y-%m-%d')<=DATE_FORMAT(last_day(end_day),'%Y-%m-%d') AND flag MOD 7=0) t4 ON t3.id=t4.id GROUP BY t3.area,t3.store_name UNION ALL \n" +
                "SELECT t3.area,t3.store_name,MAX(t3.dept_seq) AS dept_seq,0 AS leads_aim_day,0 AS leads_amount_day,0 AS test_drive_aim_day,0 AS testdrive_amount_day,0 AS locked_aim_day,0 AS locked_amount_day,0 AS leads_aim_week,0 AS leads_amount_week,0 AS test_drive_aim_week,0 AS testdrive_amount_week,0 AS locked_aim_week,0 AS locked_amount_week,0 AS locked_aim_month,0 AS locked_aim_month_16,0 AS locked_amount_16days,0 AS locked_amount_month,0 AS volume_rate,MAX(CASE WHEN t4.flag MOD 7=0 THEN t4.lead_online_drive_aim ELSE 0 END) AS lead_online_drive_aim_week,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=1 AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day AND t3.create_time<=t3.attempt_time THEN t3.customer_account_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=1 AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day THEN t3.customer_account_id END),0) AS leads_drive_1,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=2 AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day AND t3.create_time<=t3.attempt_time THEN t3.customer_account_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=2 AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day THEN t3.customer_account_id END),0) AS leads_drive_2,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=3 AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day AND t3.create_time<=t3.attempt_time THEN t3.customer_account_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=3 AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day THEN t3.customer_account_id END),0) AS leads_drive_3,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=4 AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day AND t3.create_time<=t3.attempt_time THEN t3.customer_account_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=4 AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day THEN t3.customer_account_id END),0) AS leads_drive_4,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=5 AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day AND t3.create_time<=t3.attempt_time THEN t3.customer_account_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=5 AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day THEN t3.customer_account_id END),0) AS leads_drive_5,0 AS drive_locked_aim_week,0 AS drive_locked_1,0 AS drive_locked_2,0 AS drive_locked_3,0 AS drive_locked_4,0 AS drive_locked_5 FROM (\n" +
                "SELECT t1.id,t1.area,t1.store_name,t1.dept_seq,t2.customer_account_id,t2.create_time,t2.attempt_time FROM (\n" +
                "SELECT owner_store_dept_id AS id,owner_store_dept_name AS store_name,dept_id,area,dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT area_dept_id AS id,'总计' AS store_name,dept_id,area,area_seq AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,dept_id,'全国' AS area,0 AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,999 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,0 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 0 AS id,'总计' store_name,0 AS dept_id,'云订单' AS area,999 AS dept_seq) t1 LEFT OUTER JOIN (\n" +
                "SELECT leads.owner_dept_id,leads.customer_account_id,leads.create_time,attempt.attempt_time FROM (\n" +
                "SELECT net.customer_account_id,ticket.owner_dept_id,ticket.create_time FROM (\n" +
                "SELECT leads_code,customer_account_id,business_type_name,leads_create_time FROM da_dmp_tidb.nr_sales_leads_detail_table WHERE is_net_leads=1 AND business_type_name<> '线下' AND leads_create_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) net JOIN (\n" +
                "SELECT customer_account_id,owner_dept_id,create_time FROM (\n" +
                "SELECT ticket_code,customer_account_id,first_source,owner_dept_id,DATE_FORMAT(create_time,'%Y-%m-%d') create_time,row_number() over (PARTITION BY customer_account_id ORDER BY create_time,ticket_code) num FROM da_dmp_tidb.nr_sales_ticket_detail) t2 WHERE num=1 AND create_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND create_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) ticket ON net.customer_account_id=ticket.customer_account_id) leads LEFT OUTER JOIN (\n" +
                "SELECT customer_account_id,DATE_FORMAT(begin_time,'%Y-%m-%d') AS attempt_time FROM saos_tur.rb_attempt_drive_record WHERE begin_time>=DATE_FORMAT('2021-10-12','%Y-%m-01 00:00:00') AND begin_time< DATE_FORMAT(DATE_ADD('2021-10-12',INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) attempt ON leads.customer_account_id=attempt.customer_account_id) t2 ON t1.dept_id=t2.owner_dept_id) t3 LEFT OUTER JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,id,store_code,lead_online_drive_aim FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE DATE_FORMAT('2021-10-12','%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-01') AND DATE_FORMAT('2021-10-12','%Y-%m-%d')<=DATE_FORMAT(last_day(end_day),'%Y-%m-%d') AND flag MOD 7=0) t4 ON t3.id=t4.id GROUP BY t3.area,t3.store_name) result GROUP BY area,store_name ORDER BY CASE area WHEN '全国' THEN 1 WHEN '东一区' THEN 2 WHEN '东二区' THEN 3 WHEN '西一区' THEN 4 WHEN '西二区' THEN 5 WHEN '西三区' THEN 6 WHEN '南一区' THEN 7 WHEN '南二区' THEN 8 WHEN '北一区' THEN 9 WHEN '北二区' THEN 10 WHEN '北三区' THEN 11 WHEN '其他' THEN 100 ELSE 99 END,CASE store_name WHEN '总计' THEN 0 ELSE dept_seq END) T WHERE `门店` IN ('总计')";


        sql = "SET @@SESSION.tidb_isolation_read_engines=\"tikv\"; \n" +
                "SELECT $ query_date $ AS '日期',area AS '区域',store_name AS '门店',MAX(CASE WHEN IF (leads_aim_day=0,0,leads_amount_day/leads_aim_day)>=1 AND IF (test_drive_aim_day=0,0,testdrive_amount_day/test_drive_aim_day)>=1 AND IF (locked_aim_day=0,0,locked_amount_day/locked_aim_day)>=1 THEN 3 WHEN IF (leads_aim_day=0,0,leads_amount_day/leads_aim_day)>=1 AND IF (test_drive_aim_day=0,0,testdrive_amount_day/test_drive_aim_day)>=1 THEN 2 WHEN IF (leads_aim_day=0,0,leads_amount_day/leads_aim_day)>=1 AND IF (locked_aim_day=0,0,locked_amount_day/locked_aim_day)>=1 THEN 2 WHEN IF (test_drive_aim_day=0,0,testdrive_amount_day/test_drive_aim_day)>=1 AND IF (locked_aim_day=0,0,locked_amount_day/locked_aim_day)>=1 THEN 2 WHEN IF (leads_aim_day=0,0,leads_amount_day/leads_aim_day)>=1 THEN 1 WHEN IF (test_drive_aim_day=0,0,testdrive_amount_day/test_drive_aim_day)>=1 THEN 1 WHEN IF (locked_aim_day=0,0,locked_amount_day/locked_aim_day)>=1 THEN 1 ELSE 0 END) AS '业务质量',MAX(leads_aim_day) AS '当日线下线索目标',MAX(leads_amount_day) AS '当日线下线索',MAX(leads_amount_day)-MAX(leads_aim_day) AS '当日线下线索GAP',IF (MAX(leads_aim_day)=0,0,MAX(leads_amount_day)/MAX(leads_aim_day)) AS '当日线下线索完成率',MAX(test_drive_aim_day) AS '当日试驾目标',MAX(testdrive_amount_day) AS '当日试驾量',MAX(testdrive_amount_day)-MAX(test_drive_aim_day) AS '当日试驾GAP',IF (MAX(test_drive_aim_day)=0,0,MAX(testdrive_amount_day)/MAX(test_drive_aim_day)) AS '当日试驾完成率',MAX(locked_aim_day) AS '当日净锁单目标',MAX(locked_amount_day) AS '当日净锁单',MAX(locked_amount_day)-MAX(locked_aim_day) AS '当日净锁单GAP',IF (MAX(locked_aim_day)=0,0,MAX(locked_amount_day)/MAX(locked_aim_day)) AS '当日净锁单完成率',MAX(leads_aim_week) AS '当周线下线索目标',MAX(leads_amount_week) AS '当周线下线索',MAX(leads_amount_week)-MAX(leads_aim_week) AS '当周线下线索GAP',IF (MAX(leads_aim_week)=0,0,MAX(leads_amount_week)/MAX(leads_aim_week)) AS '当周线下线索完成率',MAX(test_drive_aim_week) AS '当周试驾目标',MAX(testdrive_amount_week) AS '当周试驾量',MAX(testdrive_amount_week)-MAX(test_drive_aim_week) AS '当周试驾GAP',IF (MAX(test_drive_aim_week)=0,0,MAX(testdrive_amount_week)/MAX(test_drive_aim_week)) AS '当周试驾完成率',MAX(locked_aim_week) AS '当周净锁单目标',MAX(locked_amount_week) AS '当周净锁单',MAX(locked_amount_week)-MAX(locked_aim_week) AS '当周净锁单GAP',IF (MAX(locked_aim_week)=0,0,MAX(locked_amount_week)/MAX(locked_aim_week)) AS '当周净锁单完成率',MAX(locked_aim_month) AS '当月净锁单目标',MAX(locked_aim_month_16) AS '当月当阶段净锁单目标',MAX(locked_amount_16days) AS '当月当阶段净锁单',MAX(locked_amount_16days)/MAX(locked_aim_month_16) AS '当月当阶段净锁单完成率',MAX(locked_amount_month) AS '当月净锁单',IF (MAX(locked_aim_month)=0,0,MAX(locked_amount_month)/MAX(locked_aim_month)) AS '当月净锁单完成率',MAX(volume_rate) AS '客流转化率',MAX(lead_online_drive_aim_week) AS '线上线索到试驾转化率目标',MAX(leads_drive_1) AS '线上线索到试驾转化率W1',MAX(leads_drive_2) AS '线上线索到试驾转化率W2',MAX(leads_drive_3) AS '线上线索到试驾转化率W3',MAX(leads_drive_4) AS '线上线索到试驾转化率W4',MAX(leads_drive_5) AS '线上线索到试驾转化率W5',MAX(drive_locked_aim_week) AS '试驾到锁单转化率目标',MAX(drive_locked_1) AS '转化率W1',MAX(drive_locked_2) AS '转化率W2',MAX(drive_locked_3) AS '转化率W3',MAX(drive_locked_4) AS '转化率W4',MAX(drive_locked_5) AS '转化率W5' FROM (\n" +
                "SELECT t3.area,t3.store_name,MAX(t3.dept_seq) AS dept_seq,MAX(CASE WHEN t4.flag=1 AND t4.start_day=$ query_date $ AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t4.leads_aim ELSE 0 END) AS leads_aim_day,SUM(CASE WHEN t4.flag=1 AND t4.start_day=$ query_date $ AND t3.flag='leads' AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t3.cs ELSE 0 END) AS leads_amount_day,MAX(CASE WHEN t4.flag=1 AND t4.start_day=$ query_date $ AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t4.test_drive_aim ELSE 0 END) AS test_drive_aim_day,SUM(CASE WHEN t4.flag=1 AND t4.start_day=$ query_date $ AND t3.flag='testdrive' AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t3.cs ELSE 0 END) AS testdrive_amount_day,MAX(CASE WHEN t4.flag=1 AND t4.start_day=$ query_date $ AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t4.locked_aim ELSE 0 END) AS locked_aim_day,SUM(CASE WHEN t4.flag=1 AND t4.start_day=$ query_date $ AND t3.flag='locked' AND t3.day_key=t4.start_day AND t3.day_key=t4.end_day THEN t3.cs ELSE 0 END) AS locked_amount_day,MAX(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<=$ query_date $ AND t4.end_day>=$ query_date $ AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t4.leads_aim ELSE 0 END) AS leads_aim_week,SUM(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<=$ query_date $ AND t4.end_day>=$ query_date $ AND t3.flag='leads' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t3.cs ELSE 0 END) AS leads_amount_week,MAX(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<=$ query_date $ AND t4.end_day>=$ query_date $ AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t4.test_drive_aim ELSE 0 END) AS test_drive_aim_week,SUM(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<=$ query_date $ AND t4.end_day>=$ query_date $ AND t3.flag='testdrive' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t3.cs ELSE 0 END) AS testdrive_amount_week,MAX(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<=$ query_date $ AND t4.end_day>=$ query_date $ AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t4.locked_aim ELSE 0 END) AS locked_aim_week,SUM(CASE WHEN t4.flag MOD 7=0 AND t4.start_day<=$ query_date $ AND t4.end_day>=$ query_date $ AND t3.flag='locked' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t3.cs ELSE 0 END) AS locked_amount_week,MAX(CASE WHEN t4.flag=31 AND t4.start_day<=$ query_date $ AND t4.end_day>=$ query_date $ AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t4.locked_aim ELSE 0 END) AS locked_aim_month,MAX(CASE WHEN t4.flag=16 AND t4.start_day<=$ query_date $ AND t4.end_day>=$ query_date $ AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t4.locked_aim ELSE 0 END) AS locked_aim_month_16,SUM(CASE WHEN t4.flag=16 AND t4.start_day<=$ query_date $ AND t4.end_day>=$ query_date $ AND t3.flag='locked' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t3.cs ELSE 0 END) AS locked_amount_16days,SUM(CASE WHEN t4.flag=31 AND t4.start_day<=$ query_date $ AND t4.end_day>=$ query_date $ AND t3.flag='locked' AND t3.day_key>=t4.start_day AND t3.day_key<=t4.end_day THEN t3.cs ELSE 0 END) AS locked_amount_month,0 AS volume_rate,0 AS lead_online_drive_aim_week,0 AS leads_drive_1,0 AS leads_drive_2,0 AS leads_drive_3,0 AS leads_drive_4,0 AS leads_drive_5,0 AS drive_locked_aim_week,0 AS drive_locked_1,0 AS drive_locked_2,0 AS drive_locked_3,0 AS drive_locked_4,0 AS drive_locked_5 FROM (-- 当日、当周及当月目标及数量\n" +
                "SELECT t1.id,t1.area,t1.store_name,t1.dept_seq,IFNULL(t2.day_key,$ query_date $) AS day_key,flag,customer_account_id,cs FROM (\n" +
                "SELECT owner_store_dept_id AS id,owner_store_dept_name AS store_name,dept_id,area,dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT area_dept_id AS id,'总计' AS store_name,dept_id,area,area_seq AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,dept_id,'全国' AS area,0 AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,999 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,0 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 0 AS id,'总计' store_name,0 AS dept_id,'云订单' AS area,999 AS dept_seq) t1 LEFT OUTER JOIN (\n" +
                "SELECT day_key,real_dept_id,flag,customer_account_id,count(1) cs FROM (\n" +
                "SELECT leads.day_key,'leads' AS flag,leads.customer_account_id,-- 客户账号id\n" +
                "IFNULL(owner_dept_id,999) AS real_dept_id-- 门店编码\n" +
                "FROM (\n" +
                "SELECT DATE_FORMAT(leads_create_time,'%Y-%m-%d') AS day_key,customer_account_id FROM da_dmp_tidb.nr_sales_leads_detail_table WHERE leads_create_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND leads_create_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') AND is_net_leads=1 AND business_type_name='线下') leads LEFT OUTER JOIN (\n" +
                "SELECT customer_account_id,owner_dept_id,ROW_NUMBER() OVER (PARTITION BY customer_account_id ORDER BY create_time) AS rk FROM saos_tur.rb_ticket WHERE create_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND create_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') AND `is_delete`=0-- AND first_source = 10\n" +
                "-- AND LENGTH(TRIM(oppty_code))!=0\n" +
                "AND LENGTH(TRIM(customer_account_id)) !=0) ticket ON leads.customer_account_id=ticket.customer_account_id AND ticket.rk=1 UNION ALL \n" +
                "SELECT DATE_FORMAT(begin_time,'%Y-%m-%d') AS day_key,'testdrive' AS flag,customer_account_id,dept_id AS real_dept_id FROM saos_tur.rb_attempt_drive_record WHERE begin_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND begin_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') AND `is_delete`=0-- AND attempt_status = 20\n" +
                "UNION ALL \n" +
                "SELECT locked.day_key,'locked' AS flag,locked.customer_account_id,IFNULL(orders.employee_dept_id,0) AS real_dept_id FROM (\n" +
                "SELECT DATE_FORMAT(locked_time,'%Y-%m-%d') AS day_key,customer_account_id,sales_order_id FROM da_dmp_tidb.nr_sales_lock_detail WHERE is_clear=1 AND locked_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND locked_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) locked LEFT OUTER JOIN (\n" +
                "SELECT customer_account_id,order_code,employee_dept_id FROM saos_tur.tur_employee_order_bind WHERE lock_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND employee_type=1 AND employee_account_id<> '000000') orders ON locked.sales_order_id=orders.order_code) act GROUP BY day_key,real_dept_id,flag,customer_account_id) t2 ON t1.dept_id=t2.real_dept_id) t3 LEFT OUTER JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,id,store_code,leads_aim,test_drive_aim,locked_aim FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE DATE_FORMAT($ query_date $,'%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-%d') AND DATE_FORMAT($ query_date $,'%Y-%m-%d')<=DATE_FORMAT(end_day,'%Y-%m-%d') UNION ALL \n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,0 AS id,0 AS store_code,0 AS leads_aim,0 AS test_drive_aim,0 AS locked_aim FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE DATE_FORMAT($ query_date $,'%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-%d') AND DATE_FORMAT($ query_date $,'%Y-%m-%d')<=DATE_FORMAT(end_day,'%Y-%m-%d')) t4 ON t3.id=t4.id GROUP BY t3.area,t3.store_name UNION ALL-- 客流转化率\n" +
                "SELECT t3.area,t3.store_name,MAX(t3.dept_seq) AS dept_seq,0 AS leads_aim_day,0 AS leads_amount_day,0 AS test_drive_aim_day,0 AS testdrive_amount_day,0 AS locked_aim_day,0 AS locked_amount_day,0 AS leads_aim_week,0 AS leads_amount_week,0 AS test_drive_aim_week,0 AS testdrive_amount_week,0 AS locked_aim_week,0 AS locked_amount_week,0 AS locked_aim_month,0 AS locked_aim_month_16,0 AS locked_amount_16days,0 AS locked_amount_month,IF (MAX(volume)=0,0,IFNULL((MAX(leads_cs)-MAX(act_leads_cs))/MAX(volume),0)) AS volume_rate,0 AS lead_online_drive_aim_week,0 AS leads_drive_1,0 AS leads_drive_2,0 AS leads_drive_3,0 AS leads_drive_4,0 AS leads_drive_5,0 AS drive_locked_aim_week,0 AS drive_locked_1,0 AS drive_locked_2,0 AS drive_locked_3,0 AS drive_locked_4,0 AS drive_locked_5 FROM (\n" +
                "SELECT t1.area,t1.store_name,t1.dept_seq,SUM(IFNULL(t2.leads_cs,0)) leads_cs,SUM(IFNULL(t2.act_leads_cs,0)) act_leads_cs,SUM(IFNULL(t2.volume,0)) volume FROM (\n" +
                "SELECT owner_store_dept_id AS id,owner_store_dept_name AS store_name,dept_id,area,dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT area_dept_id AS id,'总计' AS store_name,dept_id,area,area_seq AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,dept_id,'全国' AS area,0 AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,999 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,0 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 0 AS id,'总计' store_name,0 AS dept_id,'云订单' AS area,999 AS dept_seq) t1 LEFT OUTER JOIN (\n" +
                "SELECT owner_dept_id AS dept_id,MAX(leads_cs) leads_cs,MAX(act_leads_cs) act_leads_cs,MAX(volume) volume FROM (-- 活动线下线索 后续修正\n" +
                "SELECT owner_dept_id,0 AS leads_cs,COUNT(1) act_leads_cs,0 AS volume FROM (\n" +
                "SELECT t1.leads_account_id customer_account_id,biz_code,t4.owner_dept_id,row_number() over (PARTITION BY t1.leads_account_id,t2.act_code ORDER BY t1.create_time) num FROM (\n" +
                "SELECT leads_account_id,create_time,biz_code,lead_uniq_code FROM (\n" +
                "SELECT 0 AS id,leads_account_id,create_time,biz_code,lead_uniq_code FROM saos_ccp.ccp_leads WHERE biz_code IS NOT NULL AND channel_code IN (102010) AND create_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND create_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) leads JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,0 AS id FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE flag MOD 7=0 AND id=999 AND DATE_FORMAT($ query_date $,'%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-%d') AND DATE_FORMAT($ query_date $,'%Y-%m-%d')<=DATE_FORMAT(end_day,'%Y-%m-%d')) dates ON leads.id=dates.id AND dates.start_day<=DATE_FORMAT(leads.create_time,'%Y-%m-%d') AND dates.end_day>=DATE_FORMAT(leads.create_time,'%Y-%m-%d')) t1 JOIN (\n" +
                "SELECT act_code,act_name FROM saos_mam.ma_act WHERE act_name NOT LIKE '%测试%') t2 ON t1.biz_code=t2.act_code JOIN saos_tur.rb_leads_oppty_releation t3 ON t1.lead_uniq_code=t3.leads_code JOIN (\n" +
                "SELECT owner_dept_id,oppty_code,row_number() over (PARTITION BY oppty_code ORDER BY create_time) num FROM da_dmp_tidb.nr_sales_ticket_detail) t4 ON t3.oppty_code=t4.oppty_code AND t4.num=1) t WHERE num=1 GROUP BY owner_dept_id UNION ALL-- 线下线索总量\n" +
                "SELECT owner_dept_id,COUNT(1) AS leads_cs,0 AS act_leads_cs,0 AS volume FROM (\n" +
                "SELECT day_key,customer_account_id,channel_code FROM (\n" +
                "SELECT DATE_FORMAT(leads_create_time,'%Y-%m-%d') AS day_key,customer_account_id,channel_code,0 AS id FROM da_dmp_tidb.nr_sales_leads_detail_table WHERE leads_create_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND leads_create_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') AND is_net_leads=1 AND business_type_name='线下') leads1 JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,0 AS id FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE flag MOD 7=0 AND id=999 AND DATE_FORMAT($ query_date $,'%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-%d') AND DATE_FORMAT($ query_date $,'%Y-%m-%d')<=DATE_FORMAT(end_day,'%Y-%m-%d')) dates ON leads1.id=dates.id AND dates.start_day<=leads1.day_key AND dates.end_day>=leads1.day_key) leads JOIN (\n" +
                "SELECT customer_account_id,owner_dept_id,ROW_NUMBER() OVER (PARTITION BY customer_account_id ORDER BY create_time) AS rk FROM saos_tur.rb_ticket WHERE create_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND create_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') AND `is_delete`=0-- AND first_source = 10\n" +
                "-- AND LENGTH(TRIM(oppty_code))!=0\n" +
                "AND LENGTH(TRIM(customer_account_id)) !=0) ticket ON leads.customer_account_id=ticket.customer_account_id AND ticket.rk=1 GROUP BY owner_dept_id UNION ALL-- 客流量\n" +
                "SELECT t4.id AS owner_dept_id,0 AS leads_cs,0 AS act_leads_cs,sum(volume) volume FROM (\n" +
                "SELECT camera_uuid,volume FROM (\n" +
                "SELECT DATE_FORMAT(date,'%Y-%m-%d') day_key,camera_uuid,sum(passengers_in) volume,0 AS id FROM coa.hikvision_footfall WHERE date>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND date< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') GROUP BY DATE_FORMAT(date,'%Y-%m-%d'),camera_uuid) hik JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,0 AS id FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE flag MOD 7=0 AND id=999 AND DATE_FORMAT($ query_date $,'%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-%d') AND DATE_FORMAT($ query_date $,'%Y-%m-%d')<=DATE_FORMAT(end_day,'%Y-%m-%d')) dates ON hik.id=dates.id AND dates.start_day<=hik.day_key AND dates.end_day>=hik.day_key) t1 JOIN (\n" +
                "SELECT DISTINCT camera_uuid,store_id FROM coa.hikvision_camera_device) t2 ON t1.camera_uuid=t2.camera_uuid JOIN (\n" +
                "SELECT DISTINCT CASE-- WHEN store_code IN ('RWUH02','RWUH04') THEN 'RWUH01'\n" +
                "WHEN store_code='RTNA02' THEN 'RTNA01' ELSE store_code END AS store_code,hk_store_code FROM saos_tur.tur_store_hk_relation) t3 ON t2.store_id=t3.hk_store_code JOIN (\n" +
                "SELECT id,store_code FROM saos_tur.upm_dept WHERE `is_delete`=0 AND dept_type=20) t4 ON t3.store_code=t4.store_code GROUP BY t4.id) actleads GROUP BY owner_dept_id) t2 ON t1.dept_id=t2.dept_id GROUP BY t1.area,t1.store_name,t1.dept_seq) t3 GROUP BY t3.area,t3.store_name UNION ALL-- 试驾到锁单转化率\n" +
                "SELECT t3.area,t3.store_name,MAX(t3.dept_seq) AS dept_seq,0 AS leads_aim_day,0 AS leads_amount_day,0 AS test_drive_aim_day,0 AS testdrive_amount_day,0 AS locked_aim_day,0 AS locked_amount_day,0 AS leads_aim_week,0 AS leads_amount_week,0 AS test_drive_aim_week,0 AS testdrive_amount_week,0 AS locked_aim_week,0 AS locked_amount_week,0 AS locked_aim_month,0 AS locked_aim_month_16,0 AS locked_amount_16days,0 AS locked_amount_month,0 AS volume_rate,0 AS lead_online_drive_aim_week,0 AS leads_drive_1,0 AS leads_drive_2,0 AS leads_drive_3,0 AS leads_drive_4,0 AS leads_drive_5,MAX(CASE WHEN t4.flag MOD 7=0 THEN t4.drive_locked_aim ELSE 0 END) AS drive_locked_aim_week,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=1 AND bhv_flag='order' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.locked_time>=t4.start_day AND t3.locked_time<=t4.end_day AND t3.attempt_time<=t3.locked_time THEN t3.vehicle_order_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=1 AND bhv_flag='attempt' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day THEN t3.customer_account_id END),0) AS drive_locked_1,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=2 AND bhv_flag='order' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.locked_time>=t4.start_day AND t3.locked_time<=t4.end_day AND t3.attempt_time<=t3.locked_time THEN t3.vehicle_order_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=2 AND bhv_flag='attempt' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day THEN t3.customer_account_id END),0) AS drive_locked_2,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=3 AND bhv_flag='order' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.locked_time>=t4.start_day AND t3.locked_time<=t4.end_day AND t3.attempt_time<=t3.locked_time THEN t3.vehicle_order_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=3 AND bhv_flag='attempt' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day THEN t3.customer_account_id END),0) AS drive_locked_3,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=4 AND bhv_flag='order' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.locked_time>=t4.start_day AND t3.locked_time<=t4.end_day AND t3.attempt_time<=t3.locked_time THEN t3.vehicle_order_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=4 AND bhv_flag='attempt' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day THEN t3.customer_account_id END),0) AS drive_locked_4,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=5 AND bhv_flag='order' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.locked_time>=t4.start_day AND t3.locked_time<=t4.end_day AND t3.attempt_time<=t3.locked_time THEN t3.vehicle_order_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=5 AND bhv_flag='attempt' AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day THEN t3.customer_account_id END),0) AS drive_locked_5 FROM (\n" +
                "SELECT t1.id,t1.area,t1.store_name,t1.dept_seq,t2.bhv_flag,t2.customer_account_id,t2.attempt_time,t2.locked_time,t2.vehicle_order_id FROM (\n" +
                "SELECT owner_store_dept_id AS id,owner_store_dept_name AS store_name,dept_id,area,dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT area_dept_id AS id,'总计' AS store_name,dept_id,area,area_seq AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,dept_id,'全国' AS area,0 AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,999 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,0 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 0 AS id,'总计' store_name,0 AS dept_id,'云订单' AS area,999 AS dept_seq) t1 LEFT OUTER JOIN (\n" +
                "SELECT 'attempt' AS bhv_flag,dept_id AS real_dept_id,customer_account_id,DATE_FORMAT(begin_time,'%Y-%m-%d') AS attempt_time,'' AS locked_time,'' AS vehicle_order_id FROM saos_tur.rb_attempt_drive_record WHERE begin_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND begin_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00') UNION ALL \n" +
                "SELECT 'order' AS bhv_flag,locked.dept_id AS real_dept_id,locked.customer_account_id,attempt.attempt_time,locked.locked_time,locked.vehicle_order_id FROM (\n" +
                "SELECT vehicle_order_id,locked_time,locked.customer_account_id,IFNULL(orders.dept_id,0) AS dept_id FROM (\n" +
                "SELECT vehicle_order_id,sales_order_id,DATE_FORMAT(locked_time,'%Y-%m-%d') AS locked_time,customer_account_id FROM da_dmp_tidb.nr_sales_lock_detail WHERE is_clear=1 AND sales_type<> 10 AND locked_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND locked_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) locked LEFT OUTER JOIN (\n" +
                "SELECT customer_account_id,employee_account_id,order_code,employee_dept_id AS dept_id FROM saos_tur.tur_employee_order_bind WHERE employee_type=1 AND lock_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND employee_account_id<> '000000') orders ON locked.sales_order_id=orders.order_code) locked LEFT OUTER JOIN (\n" +
                "SELECT attempt_code,customer_account_id,DATE_FORMAT(begin_time,'%Y-%m-%d') AS attempt_time,dept_id FROM saos_tur.rb_attempt_drive_record WHERE begin_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND begin_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) attempt ON attempt.customer_account_id=locked.customer_account_id) t2 ON t1.dept_id=t2.real_dept_id) t3 LEFT OUTER JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,id,store_code,drive_locked_aim FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE DATE_FORMAT($ query_date $,'%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-01') AND DATE_FORMAT($ query_date $,'%Y-%m-%d')<=DATE_FORMAT(last_day(end_day),'%Y-%m-%d') AND flag MOD 7=0) t4 ON t3.id=t4.id GROUP BY t3.area,t3.store_name UNION ALL-- 线上线索到试驾转化率 及 线上线索到锁单转化率\n" +
                "SELECT t3.area,t3.store_name,MAX(t3.dept_seq) AS dept_seq,0 AS leads_aim_day,0 AS leads_amount_day,0 AS test_drive_aim_day,0 AS testdrive_amount_day,0 AS locked_aim_day,0 AS locked_amount_day,0 AS leads_aim_week,0 AS leads_amount_week,0 AS test_drive_aim_week,0 AS testdrive_amount_week,0 AS locked_aim_week,0 AS locked_amount_week,0 AS locked_aim_month,0 AS locked_aim_month_16,0 AS locked_amount_16days,0 AS locked_amount_month,0 AS volume_rate,MAX(CASE WHEN t4.flag MOD 7=0 THEN t4.lead_online_drive_aim ELSE 0 END) AS lead_online_drive_aim_week,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=1 AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day AND t3.create_time<=t3.attempt_time THEN t3.customer_account_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=1 AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day THEN t3.customer_account_id END),0) AS leads_drive_1,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=2 AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day AND t3.create_time<=t3.attempt_time THEN t3.customer_account_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=2 AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day THEN t3.customer_account_id END),0) AS leads_drive_2,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=3 AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day AND t3.create_time<=t3.attempt_time THEN t3.customer_account_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=3 AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day THEN t3.customer_account_id END),0) AS leads_drive_3,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=4 AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day AND t3.create_time<=t3.attempt_time THEN t3.customer_account_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=4 AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day THEN t3.customer_account_id END),0) AS leads_drive_4,IFNULL(COUNT(DISTINCT CASE WHEN t4.flag/7=5 AND t3.attempt_time>=t4.start_day AND t3.attempt_time<=t4.end_day AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day AND t3.create_time<=t3.attempt_time THEN t3.customer_account_id END)/COUNT(DISTINCT CASE WHEN t4.flag/7=5 AND t3.create_time>=t4.start_day AND t3.create_time<=t4.end_day THEN t3.customer_account_id END),0) AS leads_drive_5,0 AS drive_locked_aim_week,0 AS drive_locked_1,0 AS drive_locked_2,0 AS drive_locked_3,0 AS drive_locked_4,0 AS drive_locked_5 FROM (\n" +
                "SELECT t1.id,t1.area,t1.store_name,t1.dept_seq,t2.customer_account_id,t2.create_time,t2.attempt_time FROM (\n" +
                "SELECT owner_store_dept_id AS id,owner_store_dept_name AS store_name,dept_id,area,dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT area_dept_id AS id,'总计' AS store_name,dept_id,area,area_seq AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,dept_id,'全国' AS area,0 AS dept_seq FROM da_dmp_tidb.nr_sales_dim_dept_info WHERE category=2 AND area IS NOT NULL AND CASE WHEN `is_delete`=1 THEN update_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') ELSE `is_delete`=0 END UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,999 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 999 AS id,'总计' store_name,0 AS dept_id,'全国' AS area,0 AS dept_seq UNION ALL \n" +
                "SELECT 0 AS id,'总计' store_name,0 AS dept_id,'云订单' AS area,999 AS dept_seq) t1 LEFT OUTER JOIN (\n" +
                "SELECT leads.owner_dept_id,leads.customer_account_id,leads.create_time,attempt.attempt_time FROM (\n" +
                "SELECT net.customer_account_id,ticket.owner_dept_id,ticket.create_time FROM (\n" +
                "SELECT leads_code,customer_account_id,business_type_name,leads_create_time FROM da_dmp_tidb.nr_sales_leads_detail_table WHERE is_net_leads=1 AND business_type_name<> '线下' AND leads_create_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) net JOIN (-- 工单取用户第一条\n" +
                "SELECT customer_account_id,owner_dept_id,create_time FROM (\n" +
                "SELECT ticket_code,customer_account_id,first_source,owner_dept_id,DATE_FORMAT(create_time,'%Y-%m-%d') create_time,row_number() over (PARTITION BY customer_account_id ORDER BY create_time,ticket_code) num FROM da_dmp_tidb.nr_sales_ticket_detail) t2 WHERE num=1 AND create_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND create_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) ticket ON net.customer_account_id=ticket.customer_account_id) leads LEFT OUTER JOIN (\n" +
                "SELECT customer_account_id,DATE_FORMAT(begin_time,'%Y-%m-%d') AS attempt_time FROM saos_tur.rb_attempt_drive_record WHERE begin_time>=DATE_FORMAT($ query_date $,'%Y-%m-01 00:00:00') AND begin_time< DATE_FORMAT(DATE_ADD($ query_date $,INTERVAL 1 DAY),'%Y-%m-%d 00:00:00')) attempt ON leads.customer_account_id=attempt.customer_account_id) t2 ON t1.dept_id=t2.owner_dept_id) t3 LEFT OUTER JOIN (\n" +
                "SELECT DISTINCT DATE_FORMAT(start_day,'%Y-%m-%d') AS start_day,DATE_FORMAT(end_day,'%Y-%m-%d') AS end_day,flag,id,store_code,lead_online_drive_aim FROM da_dmp_tidb.nr_sales_dim_battle_aims WHERE DATE_FORMAT($ query_date $,'%Y-%m-%d')>=DATE_FORMAT(start_day,'%Y-%m-01') AND DATE_FORMAT($ query_date $,'%Y-%m-%d')<=DATE_FORMAT(last_day(end_day),'%Y-%m-%d') AND flag MOD 7=0) t4 ON t3.id=t4.id GROUP BY t3.area,t3.store_name) result GROUP BY area,store_name ORDER BY CASE area WHEN '全国' THEN 1 WHEN '东一区' THEN 2 WHEN '东二区' THEN 3 WHEN '西一区' THEN 4 WHEN '西二区' THEN 5 WHEN '西三区' THEN 6 WHEN '南一区' THEN 7 WHEN '南二区' THEN 8 WHEN '北一区' THEN 9 WHEN '北二区' THEN 10 WHEN '北三区' THEN 11 WHEN '其他' THEN 100 ELSE 99 END,CASE store_name WHEN '总计' THEN 0 ELSE dept_seq END";

        String pattern = "(\\$)(.*?)(\\$)";
        Pattern r = Pattern.compile(pattern);
        Matcher matcher = r.matcher(sql);
        if (matcher.find()){
            sql = matcher.replaceAll("'_SYSTEM_REPLACE_'");
        }
        parserTest(sql,dbType);

    }

    public static void parserTest(String sql,String dbType){

        List<SQLStatement> sqlStatements = SQLUtils.parseStatements(sql, dbType);

        for (SQLStatement sqlStatement : sqlStatements) {
            MySqlSchemaStatVisitor mySqlSchemaStatVisitor = new MySqlSchemaStatVisitor();
            sqlStatement.accept(mySqlSchemaStatVisitor);

            // 表名
            System.out.println("表名");
            System.out.println(JSON.toJSONString(mySqlSchemaStatVisitor.getTables()));
            // 列名
            System.out.println("列名");
            System.out.println(JSON.toJSONString(mySqlSchemaStatVisitor.getColumns()));
        }

    }
}
